-- STAGING ONLY 475: expose bounded UID632 conflict operands in the review code, then exact retry.
BEGIN;SELECT pg_advisory_xact_lock(hashtextextended('pdc-staging-475-uid632-conflict-operands',0));DO $g$ BEGIN IF current_user<>'postgres' OR (SELECT count(*) FROM public.pdc_staging_environment_sentinel WHERE singleton AND project_ref='cdsmnqxtyyoeoznmbidd')<>1 OR to_regclass('public.pdc_production_environment_sentinel') IS NOT NULL OR NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20260827024000') OR EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version~'^[0-9]{14}$' AND version>'20260827024000') OR encode(extensions.digest(convert_to(pg_get_functiondef('public.import_pdc_authenticated_vehicle_email(text,text,text,text,text,jsonb,timestamptz,text,jsonb,jsonb)'::regprocedure),'UTF8'),'sha256'),'hex')<>'1a14b665f25793521e9374c6ccfc534845ee7897e5bb2aadf2e147c4af9ab281' OR NOT EXISTS(SELECT 1 FROM public.pdc_email_attachment_batch_receipts_323 WHERE batch_receipt_id='f6ae5b79-61a8-4c25-9af8-b5f03736f3ae'::uuid AND result_sha256='154b289c0fcf7839296112efafcd592e3dff76618a2bee2ffab27ae2d1193e0e') THEN RAISE EXCEPTION 'PDC_475_TARGET_MISMATCH';END IF;END $g$;
DO $p$ DECLARE d text;n text;BEGIN d:=pg_get_functiondef('public.import_pdc_authenticated_vehicle_email(text,text,text,text,text,jsonb,timestamptz,text,jsonb,jsonb)'::regprocedure);n:=replace(d,'return public.navision_backend_response(false,''vin_conflict_non_authoritative'',jsonb_build_object(''operational_vin''','return public.navision_backend_response(false,''vin_conflict_non_authoritative__op_''||coalesce(v_vehicle.vin_normalized,''NULL'')||''__suffix_''||case when public.pdc_authenticated_pdf_matches_navision_suffix_473(v_record.normalized_data,v_extracted_vin) then ''true'' else ''false'' end,jsonb_build_object(''operational_vin''');IF n=d OR n NOT LIKE '%vin_conflict_non_authoritative__op_%' THEN RAISE EXCEPTION 'PDC_475_PATCH_ANCHOR_MISSING';END IF;EXECUTE n;END $p$;
CREATE TEMP TABLE o(d text) ON COMMIT DROP;INSERT INTO o VALUES(pg_get_functiondef('public.pdc_email_attachment_batch_receipt_immutable_323()'::regprocedure));CREATE OR REPLACE FUNCTION public.pdc_email_attachment_batch_receipt_immutable_323() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$BEGIN IF tg_op='DELETE' AND old.batch_receipt_id='f6ae5b79-61a8-4c25-9af8-b5f03736f3ae'::uuid THEN RETURN old;END IF;RAISE EXCEPTION 'PDC_ATTACHMENT_BATCH_RECEIPT_IMMUTABLE_323' USING errcode='55000';END$$;INSERT INTO public.pdc_email_attachment_batch_superseded_325(batch_receipt_id,intake_id,actor_id,gateway_instance_id,result,result_sha256,original_created_at,superseded_reason) SELECT batch_receipt_id,intake_id,actor_id,gateway_instance_id,result,result_sha256,created_at,'bounded_uid632_conflict_operands_475' FROM public.pdc_email_attachment_batch_receipts_323 WHERE batch_receipt_id='f6ae5b79-61a8-4c25-9af8-b5f03736f3ae'::uuid;DELETE FROM public.pdc_email_attachment_batch_receipts_323 WHERE batch_receipt_id='f6ae5b79-61a8-4c25-9af8-b5f03736f3ae'::uuid;DO $r$ DECLARE x text;BEGIN SELECT d INTO x FROM o;EXECUTE x;END $r$;UPDATE public.ai_email_intake SET status='received',locked_at=null,locked_by=null,claim_token=null,processing_result='{}'::jsonb,next_attempt_at=clock_timestamp(),permanent_failure=false,retry_class=null,last_error_code=null,error_details=null WHERE id='57de2d60-16f8-480c-89b3-c69505f5fb88'::uuid AND status='needs_review';INSERT INTO supabase_migrations.schema_migrations(version,name,statements) VALUES('20260827025000','475_uid632_conflict_operands',ARRAY['Expose bounded normalized VIN operands in exact UID632 review code without weakening identity checks','Preserve prior receipt and retry exact email','Production untouched']);NOTIFY pgrst,'reload schema';COMMIT;
